   346→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
   347→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingSummary *CheckpointSummary, sessionFilePaths SessionFilePaths) error {
   348→	summary := CheckpointSummary{
   349→		CheckpointID:     opts.CheckpointID,
   350→		Strategy:         opts.Strategy,
   351→		Branch:           opts.Branch,
   352→		CheckpointsCount: opts.CheckpointsCount,
   353→		FilesTouched:     opts.FilesTouched,
   354→		Sessions:         []SessionFilePaths{sessionFilePaths},
   355→		TokenUsage:       opts.TokenUsage,
   356→	}
   357→
   358→	// Aggregate with existing summary if present
   359→	if existingSummary != nil {
   360→		summary.CheckpointsCount = existingSummary.CheckpointsCount + opts.CheckpointsCount
   361→		summary.FilesTouched = mergeFilesTouched(existingSummary.FilesTouched, opts.FilesTouched)
   362→		summary.TokenUsage = aggregateTokenUsage(existingSummary.TokenUsage, opts.TokenUsage)
   363→
   364→		// Copy existing sessions and append new session
   365→		summary.Sessions = make([]SessionFilePaths, len(existingSummary.Sessions)+1)
   366→		copy(summary.Sessions, existingSummary.Sessions)
   367→		summary.Sessions[len(existingSummary.Sessions)] = sessionFilePaths
   368→	}
   369→
   370→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
   371→	if err != nil {
   372→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
   373→	}
   374→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   375→	if err != nil {
   376→		return err
   377→	}
   378→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   379→		Name: basePath + paths.MetadataFileName,
   380→		Mode: filemode.Regular,
   381→		Hash: metadataHash,
   382→	}
   383→	return nil
   384→}
