   386→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
   387→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
   388→	blob, err := repo.BlobObject(hash)
   389→	if err != nil {
   390→		return nil, fmt.Errorf("failed to get blob: %w", err)
   391→	}
   392→
   393→	reader, err := blob.Reader()
   394→	if err != nil {
   395→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   396→	}
   397→	defer reader.Close()
   398→
   399→	var result T
   400→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
   401→		return nil, fmt.Errorf("failed to decode: %w", err)
   402→	}
   403→
   404→	return &result, nil
   405→}
