   412→// aggregateTokenUsage sums two TokenUsage structs.
   413→// Returns nil if both inputs are nil.
   414→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
   415→	if a == nil && b == nil {
   416→		return nil
   417→	}
   418→	result := &agent.TokenUsage{}
   419→	if a != nil {
   420→		result.InputTokens = a.InputTokens
   421→		result.CacheCreationTokens = a.CacheCreationTokens
   422→		result.CacheReadTokens = a.CacheReadTokens
   423→		result.OutputTokens = a.OutputTokens
   424→		result.APICallCount = a.APICallCount
   425→	}
   426→	if b != nil {
   427→		result.InputTokens += b.InputTokens
   428→		result.CacheCreationTokens += b.CacheCreationTokens
   429→		result.CacheReadTokens += b.CacheReadTokens
   430→		result.OutputTokens += b.OutputTokens
   431→		result.APICallCount += b.APICallCount
   432→	}
   433→	return result
   434→}
