   513→// archiveExistingSession moves existing session files to a numbered subfolder.
   514→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   515→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   516→	// Determine archive folder number
   517→	sessionCount := existingMetadata.SessionCount
   518→	if sessionCount == 0 {
   519→		sessionCount = 1 // backwards compat
   520→	}
   521→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   522→
   523→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   524→	filesToArchive := []string{
   525→		paths.MetadataFileName,
   526→		paths.TranscriptFileName,
   527→		paths.PromptFileName,
   528→		paths.ContextFileName,
   529→		paths.ContentHashFileName,
   530→	}
   531→
   532→	// Also include transcript chunk files (full.jsonl.001, full.jsonl.002, etc.)
   533→	chunkPrefix := basePath + paths.TranscriptFileName + "."
   534→	for srcPath := range entries {
   535→		if strings.HasPrefix(srcPath, chunkPrefix) {
   536→			chunkSuffix := strings.TrimPrefix(srcPath, basePath+paths.TranscriptFileName)
   537→			if idx := agent.ParseChunkIndex(paths.TranscriptFileName+chunkSuffix, paths.TranscriptFileName); idx > 0 {
   538→				filesToArchive = append(filesToArchive, paths.TranscriptFileName+chunkSuffix)
   539→			}
   540→		}
   541→	}
   542→
   543→	// Move each file to archive folder
   544→	for _, filename := range filesToArchive {
   545→		srcPath := basePath + filename
   546→		if entry, exists := entries[srcPath]; exists {
   547→			// Add to archive location
   548→			dstPath := archivePath + filename
   549→			entries[dstPath] = object.TreeEntry{
   550→				Name: dstPath,
   551→				Mode: entry.Mode,
   552→				Hash: entry.Hash,
   553→			}
   554→			// Remove from original location (will be overwritten by new session)
   555→			delete(entries, srcPath)
   556→		}
   557→	}
   558→}
