   560→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   561→// Returns sessions ordered by folder index (oldest first).
   562→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int, agentType agent.AgentType) []ArchivedSession {
   563→	var archived []ArchivedSession
   564→
   565→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   566→	// The most recent session is at the root level (not archived).
   567→	// Session count N means there are N-1 archived sessions.
   568→	for i := 1; i < sessionCount; i++ {
   569→		folderName := strconv.Itoa(i)
   570→
   571→		// Try to get the archived session subtree
   572→		subTree, err := checkpointTree.Tree(folderName)
   573→		if err != nil {
   574→			continue // Folder doesn't exist, skip
   575→		}
   576→
   577→		session := ArchivedSession{
   578→			FolderIndex: i,
   579→		}
   580→
   581→		// Read metadata to get session ID
   582→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   583→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   584→				var metadata CommittedMetadata
   585→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   586→					session.SessionID = metadata.SessionID
   587→				}
   588→			}
   589→		}
   590→
   591→		// Read transcript (handles both chunked and non-chunked formats)
   592→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   593→			session.Transcript = transcript
   594→		}
   595→
   596→		// Read prompts
   597→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   598→			if content, contentErr := file.Contents(); contentErr == nil {
   599→				session.Prompts = content
   600→			}
   601→		}
   602→
   603→		// Only add if we got a transcript
   604→		if len(session.Transcript) > 0 {
   605→			archived = append(archived, session)
   606→		}
   607→	}
   608→
   609→	return archived
   610→}
