   612→// buildCommitMessage constructs the commit message with proper trailers.
   613→// The commit subject is always "Checkpoint: <id>" for consistency.
   614→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   615→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   616→	var commitMsg strings.Builder
   617→
   618→	// Subject line is always the checkpoint ID for consistent formatting
   619→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   620→
   621→	// Include custom description in body if provided (e.g., task checkpoint details)
   622→	if opts.CommitSubject != "" {
   623→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   624→	}
   625→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   626→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   627→	if opts.Agent != "" {
   628→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   629→	}
   630→	if opts.EphemeralBranch != "" {
   631→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   632→	}
   633→	if taskMetadataPath != "" {
   634→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   635→	}
   636→
   637→	return commitMsg.String()
   638→}
