   658→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   659→// Returns nil, nil if the checkpoint doesn't exist.
   660→//
   661→// The new storage format uses numbered subdirectories for each session:
   662→//
   663→//	<checkpoint-id>/
   664→//	├── metadata.json      # CheckpointSummary with sessions map
   665→//	├── 0/                 # First session
   666→//	│   ├── metadata.json  # Session-specific metadata
   667→//	│   └── full.jsonl     # Transcript
   668→//	├── 1/                 # Second session
   669→//	└── ...
   670→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   671→	_ = ctx // Reserved for future use
   672→
   673→	tree, err := s.getSessionsBranchTree()
   674→	if err != nil {
   675→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   676→	}
   677→
   678→	checkpointPath := checkpointID.Path()
   679→	checkpointTree, err := tree.Tree(checkpointPath)
   680→	if err != nil {
   681→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   682→	}
   683→
   684→	result := &ReadCommittedResult{}
   685→
   686→	// Read root metadata.json as CheckpointSummary
   687→	var summary CheckpointSummary
   688→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   689→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   690→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   691→			json.Unmarshal([]byte(content), &summary)
   692→		}
   693→	}
   694→
   695→	// Convert CheckpointSummary to CommittedMetadata for backwards compatibility
   696→	// Note: Agent, SessionID, SessionCount, and SessionIDs are derived from session-level metadata
   697→	result.Metadata = CommittedMetadata{
   698→		CheckpointID:     summary.CheckpointID,
   699→		Strategy:         summary.Strategy,
   700→		Branch:           summary.Branch,
   701→		CheckpointsCount: summary.CheckpointsCount,
   702→		FilesTouched:     summary.FilesTouched,
   703→		SessionCount:     len(summary.Sessions),
   704→		TokenUsage:       summary.TokenUsage,
   705→	}
   706→
   707→	// Read data from the appropriate session subdirectories
   708→	if len(summary.Sessions) > 0 {
   709→		// Find the latest session index (highest numbered directory)
   710→		latestIndex := len(summary.Sessions) - 1
   711→
   712→		// Read latest session data
   713→		latestDir := strconv.Itoa(latestIndex)
   714→		if latestTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   715→			// Get agent type and session info from session-specific metadata
   716→			var agentType agent.AgentType
   717→			if sessionMetadataFile, fileErr := latestTree.File(paths.MetadataFileName); fileErr == nil {
   718→				if content, contentErr := sessionMetadataFile.Contents(); contentErr == nil {
   719→					var sessionMetadata CommittedMetadata
   720→					if jsonErr := json.Unmarshal([]byte(content), &sessionMetadata); jsonErr == nil {
   721→						agentType = sessionMetadata.Agent
   722→						// Set fields derived from session metadata
   723→						result.Metadata.Agent = sessionMetadata.Agent
   724→						result.Metadata.SessionID = sessionMetadata.SessionID
   725→						result.Metadata.CreatedAt = sessionMetadata.CreatedAt
   726→					}
   727→				}
   728→			}
   729→
   730→			// Read transcript
   731→			if transcript, transcriptErr := readTranscriptFromTree(latestTree, agentType); transcriptErr == nil && transcript != nil {
   732→				result.Transcript = transcript
   733→			}
   734→
   735→			// Read prompts
   736→			if file, fileErr := latestTree.File(paths.PromptFileName); fileErr == nil {
   737→				if content, contentErr := file.Contents(); contentErr == nil {
   738→					result.Prompts = content
   739→				}
   740→			}
   741→
   742→			// Read context
   743→			if file, fileErr := latestTree.File(paths.ContextFileName); fileErr == nil {
   744→				if content, contentErr := file.Contents(); contentErr == nil {
   745→					result.Context = content
   746→				}
   747→			}
   748→		}
   749→
   750→		// Read archived sessions (all except the latest)
   751→		result.ArchivedSessions = s.readArchivedSessionsFromSummary(checkpointTree, summary)
   752→	}
   753→
   754→	return result, nil
   755→}
