   779→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   780→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   781→				var metadata CommittedMetadata
   782→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   783→					session.SessionID = metadata.SessionID
   784→					agentType = metadata.Agent
   785→				}
   786→			}
   787→		}
   788→
   789→		// Read transcript (handles both chunked and non-chunked formats)
   790→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   791→			session.Transcript = transcript
