   810→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   811→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   812→//
   813→
   814→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   815→	_ = ctx // Reserved for future use
   816→
   817→	tree, err := s.getSessionsBranchTree()
   818→	if err != nil {
   819→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   820→	}
   821→
   822→	var checkpoints []CommittedInfo
   823→
   824→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   825→	for _, bucketEntry := range tree.Entries {
   826→		if bucketEntry.Mode != filemode.Dir {
   827→			continue
   828→		}
   829→		// Bucket should be 2 hex chars
   830→		if len(bucketEntry.Name) != 2 {
   831→			continue
   832→		}
   833→
   834→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   835→		if treeErr != nil {
   836→			continue
   837→		}
   838→
   839→		// Each entry in the bucket is the remaining part of the checkpoint ID
   840→		for _, checkpointEntry := range bucketTree.Entries {
   841→			if checkpointEntry.Mode != filemode.Dir {
   842→				continue
   843→			}
   844→
   845→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   846→			if cpTreeErr != nil {
   847→				continue
   848→			}
   849→
   850→			// Reconstruct checkpoint ID: <bucket><remaining>
   851→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   852→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   853→			if cpIDErr != nil {
   854→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   855→				continue
   856→			}
   857→
   858→			info := CommittedInfo{
   859→				CheckpointID: checkpointID,
   860→			}
   861→
   862→			// Get details from root metadata file (CheckpointSummary format)
   863→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   864→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   865→					var summary CheckpointSummary
   866→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
   867→						info.CheckpointsCount = summary.CheckpointsCount
   868→						info.FilesTouched = summary.FilesTouched
   869→						info.SessionCount = len(summary.Sessions)
   870→
   871→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
   872→						if len(summary.Sessions) > 0 {
   873→							latestIndex := len(summary.Sessions) - 1
   874→							latestDir := strconv.Itoa(latestIndex)
   875→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   876→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
   877→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
   878→										var sessionMetadata CommittedMetadata
   879→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   880→											info.Agent = sessionMetadata.Agent
   881→											info.SessionID = sessionMetadata.SessionID
   882→											info.CreatedAt = sessionMetadata.CreatedAt
   883→										}
   884→									}
   885→								}
   886→							}
   887→						}
   888→					}
   889→				}
   890→			}
   891→
   892→			checkpoints = append(checkpoints, info)
   893→		}
   894→	}
   895→
   896→	// Sort by time (most recent first)
   897→	sort.Slice(checkpoints, func(i, j int) bool {
   898→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   899→	})
   900→
   901→	return checkpoints, nil
   902→}
