   922→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   923→func (s *GitStore) GetSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   924→	result, err := s.ReadCommitted(context.Background(), cpID)
   925→	if err != nil {
