   951→// UpdateSummary updates the summary field in the latest session's metadata.
   952→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   953→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   954→	_ = ctx // Reserved for future use
   955→
   956→	// Ensure sessions branch exists
   957→	if err := s.ensureSessionsBranch(); err != nil {
   958→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
   959→	}
   960→
   961→	// Get current branch tip and flatten tree
   962→	ref, entries, err := s.getSessionsBranchEntries()
   963→	if err != nil {
   964→		return err
   965→	}
   966→
   967→	// Read root CheckpointSummary to find the latest session
   968→	basePath := checkpointID.Path() + "/"
   969→	rootMetadataPath := basePath + paths.MetadataFileName
   970→	entry, exists := entries[rootMetadataPath]
   971→	if !exists {
   972→		return ErrCheckpointNotFound
   973→	}
   974→
   975→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
   976→	if err != nil {
   977→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
   978→	}
   979→
   980→	// Find the latest session's metadata path
   981→	latestIndex := len(checkpointSummary.Sessions) - 1
   982→	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
   983→	sessionEntry, exists := entries[sessionMetadataPath]
   984→	if !exists {
   985→		return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
   986→	}
   987→
   988→	// Read and update session metadata
   989→	existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
   990→	if err != nil {
   991→		return fmt.Errorf("failed to read session metadata: %w", err)
   992→	}
   993→
   994→	// Update the summary
   995→	existingMetadata.Summary = summary
   996→
   997→	// Write updated session metadata
   998→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
   999→	if err != nil {
  1000→		return fmt.Errorf("failed to marshal metadata: %w", err)
  1001→	}
  1002→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
  1003→	if err != nil {
  1004→		return fmt.Errorf("failed to create metadata blob: %w", err)
  1005→	}
  1006→	entries[sessionMetadataPath] = object.TreeEntry{
  1007→		Name: sessionMetadataPath,
  1008→		Mode: filemode.Regular,
  1009→		Hash: metadataHash,
  1010→	}
  1011→
  1012→	// Build and commit
  1013→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
  1014→	if err != nil {
  1015→		return err
  1016→	}
  1017→
  1018→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
  1019→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
  1020→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
  1021→	if err != nil {
  1022→		return err
  1023→	}
  1024→
  1025→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1026→	newRef := plumbing.NewHashReference(refName, newCommitHash)
  1027→	if err := s.repo.Storer.SetReference(newRef); err != nil {
  1028→		return fmt.Errorf("failed to set branch reference: %w", err)
  1029→	}
  1030→
  1031→	return nil
  1032→}
