  1034→// ensureSessionsBranch ensures the entire/sessions branch exists.
  1035→func (s *GitStore) ensureSessionsBranch() error {
  1036→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1037→	_, err := s.repo.Reference(refName, true)
  1038→	if err == nil {
  1039→		return nil // Branch exists
  1040→	}
  1041→
  1042→	// Create orphan branch with empty tree
  1043→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
  1044→	if err != nil {
  1045→		return err
  1046→	}
  1047→
  1048→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
  1049→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
  1050→	if err != nil {
  1051→		return err
  1052→	}
  1053→
  1054→	newRef := plumbing.NewHashReference(refName, commitHash)
  1055→	if err := s.repo.Storer.SetReference(newRef); err != nil {
  1056→		return fmt.Errorf("failed to set branch reference: %w", err)
  1057→	}
  1058→	return nil
  1059→}
