  1061→// getSessionsBranchTree returns the tree object for the entire/sessions branch.
  1062→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
  1063→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1064→	ref, err := s.repo.Reference(refName, true)
  1065→	if err != nil {
  1066→		return nil, fmt.Errorf("sessions branch not found: %w", err)
  1067→	}
  1068→
  1069→	commit, err := s.repo.CommitObject(ref.Hash())
  1070→	if err != nil {
  1071→		return nil, fmt.Errorf("failed to get commit object: %w", err)
  1072→	}
  1073→
  1074→	tree, err := commit.Tree()
  1075→	if err != nil {
  1076→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
  1077→	}
  1078→
  1079→	return tree, nil
  1080→}
