  1082→// CreateBlobFromContent creates a blob object from in-memory content.
  1083→// Exported for use by strategy package (session_test.go)
  1084→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1085→	obj := repo.Storer.NewEncodedObject()
  1086→	obj.SetType(plumbing.BlobObject)
  1087→	obj.SetSize(int64(len(content)))
  1088→
  1089→	writer, err := obj.Writer()
  1090→	if err != nil {
  1091→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1092→	}
  1093→
  1094→	_, err = writer.Write(content)
  1095→	if err != nil {
  1096→		_ = writer.Close()
  1097→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1098→	}
  1099→	if err := writer.Close(); err != nil {
  1100→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1101→	}
  1102→
  1103→	hash, err := repo.Storer.SetEncodedObject(obj)
  1104→	if err != nil {
  1105→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1106→	}
  1107→	return hash, nil
  1108→}
