  1110→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1111→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1112→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1113→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1114→		if err != nil {
  1115→			return err
  1116→		}
  1117→		if info.IsDir() {
  1118→			return nil
  1119→		}
  1120→
  1121→		// Skip symlinks to prevent reading files outside the metadata directory.
  1122→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1123→		// then be captured in the checkpoint and stored in git history.
  1124→		if info.Mode()&os.ModeSymlink != 0 {
  1125→			return nil
  1126→		}
  1127→
  1128→		// Get relative path within metadata dir
  1129→		relPath, err := filepath.Rel(metadataDir, path)
  1130→		if err != nil {
  1131→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1132→		}
  1133→
  1134→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1135→		if strings.HasPrefix(relPath, "..") {
  1136→			return fmt.Errorf("path traversal detected: %s", relPath)
  1137→		}
  1138→
  1139→		// Create blob from file
  1140→		blobHash, mode, err := createBlobFromFile(s.repo, path)
  1141→		if err != nil {
  1142→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1143→		}
  1144→
  1145→		// Store at checkpoint path
  1146→		fullPath := basePath + relPath
  1147→		entries[fullPath] = object.TreeEntry{
  1148→			Name: fullPath,
  1149→			Mode: mode,
  1150→			Hash: blobHash,
  1151→		}
  1152→
  1153→		return nil
  1154→	})
  1155→	if err != nil {
  1156→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1157→	}
  1158→	return nil
  1159→}
