  1161→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1162→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1163→	// Get repository config (includes local settings)
  1164→	cfg, err := repo.Config()
  1165→	if err == nil {
  1166→		name = cfg.User.Name
  1167→		email = cfg.User.Email
  1168→	}
  1169→
  1170→	// Provide sensible defaults if git user is not configured
  1171→	if name == "" {
  1172→		name = "Unknown"
  1173→	}
  1174→	if email == "" {
  1175→		email = "unknown@local"
  1176→	}
  1177→
  1178→	return name, email
  1179→}
