  1181→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1182→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1183→// The agentType is used for reassembling chunks in the correct format.
  1184→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1185→	// Collect all transcript-related files
  1186→	var chunkFiles []string
  1187→	var hasBaseFile bool
  1188→
  1189→	for _, entry := range tree.Entries {
  1190→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1191→			hasBaseFile = true
  1192→		}
  1193→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1194→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1195→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1196→			if idx > 0 {
  1197→				chunkFiles = append(chunkFiles, entry.Name)
  1198→			}
  1199→		}
  1200→	}
  1201→
  1202→	// If we have chunk files, read and reassemble them
  1203→	if len(chunkFiles) > 0 {
  1204→		// Sort chunk files by index
  1205→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1206→
  1207→		// Check if base file should be included as chunk 0.
  1208→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1209→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1210→		if hasBaseFile {
  1211→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1212→		}
  1213→
  1214→		var chunks [][]byte
  1215→		for _, chunkFile := range chunkFiles {
  1216→			file, err := tree.File(chunkFile)
  1217→			if err != nil {
  1218→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1219→					slog.String("chunk_file", chunkFile),
  1220→					slog.String("error", err.Error()),
  1221→				)
  1222→				continue
  1223→			}
  1224→			content, err := file.Contents()
  1225→			if err != nil {
  1226→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1227→					slog.String("chunk_file", chunkFile),
  1228→					slog.String("error", err.Error()),
  1229→				)
  1230→				continue
  1231→			}
  1232→			chunks = append(chunks, []byte(content))
  1233→		}
  1234→
  1235→		if len(chunks) > 0 {
  1236→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1237→			if err != nil {
  1238→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1239→			}
  1240→			return result, nil
  1241→		}
  1242→	}
  1243→
  1244→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1245→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1246→		if content, err := file.Contents(); err == nil {
  1247→			return []byte(content), nil
  1248→		}
  1249→	}
  1250→
  1251→	// Try legacy filename
  1252→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1253→		if content, err := file.Contents(); err == nil {
  1254→			return []byte(content), nil
  1255→		}
  1256→	}
  1257→
  1258→	return nil, nil
  1259→}
