    26→// GetSessionInfo returns the current session info.
    27→func (s *ManualCommitStrategy) GetSessionInfo() (*SessionInfo, error) {
    28→	repo, err := OpenRepository()
    29→	if err != nil {
    30→		return nil, fmt.Errorf("failed to open git repository: %w", err)
    31→	}
    32→
    33→	// Check if we're on a shadow branch
    34→	head, err := repo.Head()
    35→	if err != nil {
    36→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
    37→	}
    38→
    39→	if head.Name().IsBranch() {
    40→		branchName := head.Name().Short()
    41→		if strings.HasPrefix(branchName, shadowBranchPrefix) {
    42→			return nil, ErrNoSession
    43→		}
    44→	}
    45→
    46→	// Find sessions for current HEAD
    47→	sessions, err := s.findSessionsForCommit(head.Hash().String())
    48→	if err != nil || len(sessions) == 0 {
    49→		return nil, ErrNoSession
    50→	}
    51→
    52→	// Return info for most recent session
    53→	state := sessions[0]
    54→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
    55→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
    56→
    57→	info := &SessionInfo{
    58→		SessionID: state.SessionID,
    59→		Reference: shadowBranchName,
    60→	}
    61→
    62→	if ref, err := repo.Reference(refName, true); err == nil {
    63→		info.CommitHash = ref.Hash().String()
    64→	}
    65→
    66→	return info, nil
    67→}
