    98→// GetSessionContext returns the context.md content for a session.
    99→// For manual-commit strategy, reads from the entire/sessions branch using the sessions map.
   100→func (s *ManualCommitStrategy) GetSessionContext(sessionID string) string {
   101→	// Find a checkpoint for this session
   102→	checkpoints, err := s.getCheckpointsForSession(sessionID)
   103→	if err != nil || len(checkpoints) == 0 {
   104→		return ""
   105→	}
   106→
   107→	// Use the most recent checkpoint
   108→	sort.Slice(checkpoints, func(i, j int) bool {
   109→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   110→	})
   111→	checkpointID := checkpoints[0].CheckpointID
   112→
   113→	repo, err := OpenRepository()
   114→	if err != nil {
   115→		return ""
   116→	}
   117→
   118→	// Get the sessions branch
   119→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   120→	ref, err := repo.Reference(refName, true)
   121→	if err != nil {
   122→		return ""
   123→	}
   124→
   125→	commit, err := repo.CommitObject(ref.Hash())
   126→	if err != nil {
   127→		return ""
   128→	}
   129→
   130→	tree, err := commit.Tree()
   131→	if err != nil {
   132→		return ""
   133→	}
   134→
   135→	// Get checkpoint tree
   136→	checkpointTree, err := tree.Tree(checkpointID.Path())
   137→	if err != nil {
   138→		return ""
   139→	}
   140→
   141→	// Read root metadata to find session's context path from sessions map
   142→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
   143→	if err != nil {
   144→		return ""
   145→	}
   146→
   147→	metadataContent, err := metadataFile.Contents()
   148→	if err != nil {
   149→		return ""
   150→	}
   151→
   152→	var summary checkpoint.CheckpointSummary
   153→	if err := json.Unmarshal([]byte(metadataContent), &summary); err != nil {
   154→		return ""
   155→	}
   156→
   157→	// Look up context path from sessions array
   158→	// Try to find the session by reading each session's metadata, or fall back to latest
   159→	var sessionPaths checkpoint.SessionFilePaths
   160→	if len(summary.Sessions) > 0 {
   161→		// Use the latest session by default
   162→		latestIndex := len(summary.Sessions) - 1
   163→		sessionPaths = summary.Sessions[latestIndex]
   164→	} else {
   165→		return ""
   166→	}
   167→
   168→	// Read context from the session's subdirectory
   169→	if sessionPaths.Context == "" {
   170→		return ""
   171→	}
   172→	file, err := checkpointTree.File(sessionPaths.Context)
   173→	if err != nil {
   174→		return ""
   175→	}
   176→	content, err := file.Contents()
   177→	if err != nil {
   178→		return ""
   179→	}
   180→	return content
   181→}
