   183→// GetCheckpointLog returns the session transcript for a specific checkpoint.
   184→// For manual-commit strategy, metadata is stored at sharded paths on entire/sessions branch.
   185→func (s *ManualCommitStrategy) GetCheckpointLog(checkpoint Checkpoint) ([]byte, error) {
   186→	if checkpoint.CheckpointID.IsEmpty() {
   187→		return nil, ErrNoMetadata
   188→	}
   189→	return s.getCheckpointLog(checkpoint.CheckpointID)
