   192→// GetAdditionalSessions implements SessionSource interface.
   193→// Returns active sessions from .git/entire-sessions/ that haven't yet been condensed.
   194→func (s *ManualCommitStrategy) GetAdditionalSessions() ([]*Session, error) {
   195→	activeStates, err := s.listAllSessionStates()
   196→	if err != nil {
   197→		return nil, fmt.Errorf("failed to list session states: %w", err)
   198→	}
   199→
   200→	if len(activeStates) == 0 {
   201→		return nil, nil
   202→	}
   203→
   204→	var sessions []*Session
   205→	for _, state := range activeStates {
   206→		session := &Session{
   207→			ID:          state.SessionID,
   208→			Description: NoDescription,
   209→			Strategy:    StrategyNameManualCommit,
   210→			StartTime:   state.StartedAt,
   211→		}
   212→
   213→		// Try to get description from shadow branch
   214→		if description := s.getDescriptionFromShadowBranch(state.SessionID, state.BaseCommit, state.WorktreeID); description != "" {
   215→			session.Description = description
   216→		}
   217→
   218→		sessions = append(sessions, session)
   219→	}
   220→
   221→	return sessions, nil
   222→}
