   224→// getDescriptionFromShadowBranch reads the session description from the shadow branch.
   225→// sessionID is expected to be an Entire session ID (already date-prefixed like "2026-01-12-abc123").
   226→func (s *ManualCommitStrategy) getDescriptionFromShadowBranch(sessionID, baseCommit, worktreeID string) string {
   227→	repo, err := OpenRepository()
   228→	if err != nil {
   229→		return ""
   230→	}
   231→
   232→	shadowBranchName := getShadowBranchNameForCommit(baseCommit, worktreeID)
   233→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   234→	ref, err := repo.Reference(refName, true)
   235→	if err != nil {
   236→		return ""
   237→	}
   238→
   239→	commit, err := repo.CommitObject(ref.Hash())
   240→	if err != nil {
   241→		return ""
   242→	}
   243→
   244→	tree, err := commit.Tree()
   245→	if err != nil {
   246→		return ""
   247→	}
   248→
   249→	// Use SessionMetadataDirFromEntireID since sessionID is already an Entire session ID
   250→	// (with date prefix like "2026-01-12-abc123")
   251→	metadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   252→	return getSessionDescriptionFromTree(tree, metadataDir)
   253→}
