   398→// Helper function to create a test metadata branch with a multi-session checkpoint
   399→func createTestMultiSessionCheckpoint(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID, primarySessionID string, allSessionIDs []string) {
   400→	t.Helper()
   401→
   402→	entries := make(map[string]object.TreeEntry)
   403→	checkpointPath := checkpointID.Path()
   404→
   405→	// Create session-level metadata for each session
   406→	var sessionFilePaths []checkpoint.SessionFilePaths
   407→	for i, sessionID := range allSessionIDs {
   408→		sessionDir := strconv.Itoa(i)
   409→		sessionMetadata := checkpoint.CommittedMetadata{
   410→			CheckpointID: checkpointID,
   411→			SessionID:    sessionID,
   412→			CreatedAt:    time.Now(),
   413→		}
   414→		sessionMetadataJSON, err := json.Marshal(sessionMetadata)
   415→		if err != nil {
   416→			t.Fatalf("failed to marshal session metadata: %v", err)
   417→		}
   418→		sessionMetadataBlobHash, err := checkpoint.CreateBlobFromContent(repo, sessionMetadataJSON)
   419→		if err != nil {
   420→			t.Fatalf("failed to create session metadata blob: %v", err)
   421→		}
   422→		sessionMetadataPath := checkpointPath + "/" + sessionDir + "/" + paths.MetadataFileName
   423→		entries[sessionMetadataPath] = object.TreeEntry{
   424→			Name: sessionMetadataPath,
   425→			Mode: filemode.Regular,
   426→			Hash: sessionMetadataBlobHash,
   427→		}
   428→		sessionFilePaths = append(sessionFilePaths, checkpoint.SessionFilePaths{
   429→			Metadata: sessionDir + "/" + paths.MetadataFileName,
   430→		})
   431→	}
   432→
   433→	// Create root CheckpointSummary with Sessions array
   434→	summary := checkpoint.CheckpointSummary{
   435→		CheckpointID: checkpointID,
   436→		Sessions:     sessionFilePaths,
   437→	}
   438→	summaryJSON, err := json.Marshal(summary)
   439→	if err != nil {
   440→		t.Fatalf("failed to marshal summary: %v", err)
   441→	}
   442→	summaryBlobHash, err := checkpoint.CreateBlobFromContent(repo, summaryJSON)
   443→	if err != nil {
   444→		t.Fatalf("failed to create summary blob: %v", err)
   445→	}
   446→	entries[checkpointPath+"/"+paths.MetadataFileName] = object.TreeEntry{
   447→		Name: checkpointPath + "/" + paths.MetadataFileName,
   448→		Mode: filemode.Regular,
   449→		Hash: summaryBlobHash,
   450→	}
   451→
   452→	// Build tree
   453→	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
   454→	if err != nil {
   455→		t.Fatalf("failed to build tree: %v", err)
   456→	}
   457→
   458→	// Create orphan commit
   459→	now := time.Now()
   460→	sig := object.Signature{
   461→		Name:  "Test",
   462→		Email: "test@test.com",
   463→		When:  now,
