   495→// Helper function to create a test metadata branch with a checkpoint and optional prompt
   496→func createTestMetadataBranchWithPrompt(t *testing.T, repo *git.Repository, sessionID string, checkpointID id.CheckpointID, prompt string) {
   497→	t.Helper()
   498→
   499→	// Create empty tree for orphan commit
   500→	entries := make(map[string]object.TreeEntry)
   501→
   502→	checkpointPath := checkpointID.Path()
   503→	sessionDir := "0" // First session
   504→
   505→	// Create session-level metadata in 0/ subdirectory
   506→	sessionMetadata := CheckpointInfo{
   507→		CheckpointID: checkpointID,
   508→		SessionID:    sessionID,
   509→		CreatedAt:    time.Now(),
   510→	}
   511→	sessionMetadataJSON, err := json.Marshal(sessionMetadata)
   512→	if err != nil {
   513→		t.Fatalf("failed to marshal session metadata: %v", err)
   514→	}
   515→	sessionMetadataBlobHash, err := checkpoint.CreateBlobFromContent(repo, sessionMetadataJSON)
   516→	if err != nil {
   517→		t.Fatalf("failed to create session metadata blob: %v", err)
   518→	}
   519→	sessionMetadataPath := checkpointPath + "/" + sessionDir + "/" + paths.MetadataFileName
   520→	entries[sessionMetadataPath] = object.TreeEntry{
   521→		Name: sessionMetadataPath,
   522→		Mode: filemode.Regular,
   523→		Hash: sessionMetadataBlobHash,
   524→	}
   525→
   526→	// Add prompt.txt in session subdirectory if provided
   527→	promptPath := ""
   528→	if prompt != "" {
   529→		promptBlobHash, promptErr := checkpoint.CreateBlobFromContent(repo, []byte(prompt))
   530→		if promptErr != nil {
   531→			t.Fatalf("failed to create prompt blob: %v", promptErr)
   532→		}
   533→		promptPath = sessionDir + "/" + paths.PromptFileName
   534→		fullPromptPath := checkpointPath + "/" + promptPath
   535→		entries[fullPromptPath] = object.TreeEntry{
   536→			Name: fullPromptPath,
   537→			Mode: filemode.Regular,
   538→			Hash: promptBlobHash,
   539→		}
   540→	}
   541→
   542→	// Create root CheckpointSummary
   543→	rootSummary := checkpoint.CheckpointSummary{
   544→		CheckpointID: checkpointID,
   545→		Sessions: []checkpoint.SessionFilePaths{
   546→			{
   547→				Metadata: sessionDir + "/" + paths.MetadataFileName,
   548→				Prompt:   promptPath,
   549→			},
   550→		},
   551→	}
   552→	summaryJSON, err := json.Marshal(rootSummary)
   553→	if err != nil {
   554→		t.Fatalf("failed to marshal root summary: %v", err)
   555→	}
   556→	summaryBlobHash, err := checkpoint.CreateBlobFromContent(repo, summaryJSON)
   557→	if err != nil {
   558→		t.Fatalf("failed to create summary blob: %v", err)
   559→	}
   560→	rootMetadataPath := checkpointPath + "/" + paths.MetadataFileName
   561→	entries[rootMetadataPath] = object.TreeEntry{
   562→		Name: rootMetadataPath,
   563→		Mode: filemode.Regular,
   564→		Hash: summaryBlobHash,
   565→	}
   566→
   567→	// Build tree
   568→	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
   569→	if err != nil {
   570→		t.Fatalf("failed to build tree: %v", err)
   571→	}
   572→
   573→	// Create orphan commit
   574→	now := time.Now()
   575→	sig := object.Signature{
   576→		Name:  "Test",
   577→		Email: "test@test.com",
   578→		When:  now,
   579→	}
   580→	commit := &object.Commit{
   581→		TreeHash:  treeHash,
   582→		Author:    sig,
   583→		Committer: sig,
   584→		Message:   "Test checkpoint\n\n" + trailers.SessionTrailerKey + ": " + sessionID,
   585→	}
   586→
   587→	commitObj := repo.Storer.NewEncodedObject()
   588→	if err := commit.Encode(commitObj); err != nil {
   589→		t.Fatalf("failed to encode commit: %v", err)
   590→	}
   591→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   592→	if err != nil {
   593→		t.Fatalf("failed to store commit: %v", err)
   594→	}
   595→
   596→	// Create branch reference
   597→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   598→	ref := plumbing.NewHashReference(refName, commitHash)
   599→	if err := repo.Storer.SetReference(ref); err != nil {
   600→		t.Fatalf("failed to create branch: %v", err)
   601→	}
   602→}
