    15→// TestGeminiConcurrentSessionWarning_BlocksFirstPrompt verifies that when a user starts
    16→// a new Gemini session while another session has uncommitted changes (checkpoints),
    17→// the first prompt is blocked with a Gemini-format JSON response (decision: block).
    18→func TestGeminiConcurrentSessionWarning_BlocksFirstPrompt(t *testing.T) {
    19→	env := NewTestEnv(t)
    20→	defer env.Cleanup()
    21→
    22→	env.InitRepo()
    23→	env.WriteFile("README.md", "# Test")
    24→	env.GitAdd("README.md")
    25→	env.GitCommit("Initial commit")
    26→	env.GitCheckoutNewBranch("feature/test")
    27→	env.InitEntireWithAgent(strategy.StrategyNameManualCommit, "gemini")
    28→
    29→	// Start session A and create a checkpoint
    30→	sessionA := env.NewGeminiSession()
    31→	if err := env.SimulateGeminiBeforeAgent(sessionA.ID); err != nil {
    32→		t.Fatalf("SimulateGeminiBeforeAgent (sessionA) failed: %v", err)
    33→	}
    34→
    35→	env.WriteFile("file.txt", "content from session A")
    36→	sessionA.CreateGeminiTranscript("Add file", []FileChange{{Path: "file.txt", Content: "content from session A"}})
    37→	if err := env.SimulateGeminiSessionEnd(sessionA.ID, sessionA.TranscriptPath); err != nil {
    38→		t.Fatalf("SimulateGeminiSessionEnd (sessionA) failed: %v", err)
    39→	}
    40→
    41→	// Verify session A has checkpoints
    42→	stateA, err := env.GetSessionState(sessionA.ID)
    43→	if err != nil {
    44→		t.Fatalf("GetSessionState (sessionA) failed: %v", err)
    45→	}
    46→	if stateA == nil {
    47→		t.Fatal("Session A state should exist after SessionEnd hook")
    48→	}
    49→	if stateA.CheckpointCount == 0 {
    50→		t.Fatal("Session A should have at least 1 checkpoint")
    51→	}
    52→	t.Logf("Session A has %d checkpoint(s)", stateA.CheckpointCount)
    53→
    54→	// Start session B - first prompt should be blocked
    55→	sessionB := env.NewGeminiSession()
    56→	output := env.SimulateGeminiBeforeAgentWithOutput(sessionB.ID)
    57→
    58→	// Gemini blocking exits with code 0 (JSON parsed) and decision "block"
    59→	if output.Err != nil {
    60→		t.Fatalf("Hook should exit with code 0 for blocking, got error: %v", output.Err)
    61→	}
    62→
    63→	// Parse the JSON response (Gemini format)
    64→	var response struct {
    65→		Decision string `json:"decision"`
    66→		Reason   string `json:"reason"`
    67→	}
    68→	if err := json.Unmarshal(output.Stdout, &response); err != nil {
    69→		t.Fatalf("Failed to parse JSON response: %v\nStdout: %s", err, output.Stdout)
    70→	}
    71→
    72→	// Verify decision is block
    73→	if response.Decision != "block" {
    74→		t.Errorf("Expected decision:block in JSON response, got: %s", response.Decision)
    75→	}
    76→
    77→	// Verify reason contains expected message
    78→	expectedMessage := "Another session is active"
    79→	if !strings.Contains(response.Reason, expectedMessage) {
    80→		t.Errorf("Reason should contain %q, got: %s", expectedMessage, response.Reason)
    81→	}
    82→
    83→	// Verify the resume command mentions gemini --resume
    84→	expectedResumeCmd := "gemini --resume"
    85→	if !strings.Contains(response.Reason, expectedResumeCmd) {
    86→		t.Errorf("Reason should contain %q, got: %s", expectedResumeCmd, response.Reason)
    87→	}
    88→
    89→	t.Logf("Received expected blocking response: %s", output.Stdout)
    90→}
