   136→// TestGeminiConcurrentSessionWarning_SubsequentPromptsSucceed verifies that after the
   137→// warning is shown, subsequent prompts in the same session proceed normally.
   138→func TestGeminiConcurrentSessionWarning_SubsequentPromptsSucceed(t *testing.T) {
   139→	env := NewTestEnv(t)
   140→	defer env.Cleanup()
   141→
   142→	env.InitRepo()
   143→	env.WriteFile("README.md", "# Test")
   144→	env.GitAdd("README.md")
   145→	env.GitCommit("Initial commit")
   146→	env.GitCheckoutNewBranch("feature/test")
   147→	env.InitEntireWithAgent(strategy.StrategyNameManualCommit, "gemini")
   148→
   149→	// Start session A and create a checkpoint
   150→	sessionA := env.NewGeminiSession()
   151→	if err := env.SimulateGeminiBeforeAgent(sessionA.ID); err != nil {
   152→		t.Fatalf("SimulateGeminiBeforeAgent (sessionA) failed: %v", err)
   153→	}
   154→
   155→	env.WriteFile("file.txt", "content")
   156→	sessionA.CreateGeminiTranscript("Add file", []FileChange{{Path: "file.txt", Content: "content"}})
   157→	if err := env.SimulateGeminiAfterAgent(sessionA.ID, sessionA.TranscriptPath); err != nil {
   158→		t.Fatalf("SimulateGeminiAfterAgent (sessionA) failed: %v", err)
   159→	}
   160→
   161→	// Start session B - first prompt is blocked (exits with code 0, decision: block)
   162→	sessionB := env.NewGeminiSession()
   163→	output1 := env.SimulateGeminiBeforeAgentWithOutput(sessionB.ID)
   164→
   165→	// Verify first prompt was blocked (exit code 0 with decision: block)
   166→	if output1.Err != nil {
   167→		t.Fatalf("First prompt should exit with code 0, got error: %v", output1.Err)
   168→	}
   169→
   170→	var response1 struct {
   171→		Decision string `json:"decision"`
   172→	}
   173→	if err := json.Unmarshal(output1.Stdout, &response1); err != nil {
   174→		t.Fatalf("Failed to parse first response: %v", err)
   175→	}
   176→	if response1.Decision != "block" {
   177→		t.Fatalf("First prompt should have decision:block, got: %s", response1.Decision)
   178→	}
   179→	t.Log("First prompt correctly blocked")
   180→
   181→	// Second prompt in session B should PROCEED normally (both sessions capture checkpoints)
   182→	// The warning was shown on first prompt, but subsequent prompts continue to capture state
   183→	output2 := env.SimulateGeminiBeforeAgentWithOutput(sessionB.ID)
   184→
   185→	// The hook should succeed
   186→	if output2.Err != nil {
   187→		t.Errorf("Second prompt should succeed, got error: %v", output2.Err)
   188→	}
   189→
   190→	// The hook should process normally (capture state) - no blocking response
   191→	if len(output2.Stdout) > 0 {
   192→		// Check if it's a blocking JSON response (which it shouldn't be)
   193→		var blockResponse struct {
   194→			Decision string `json:"decision"`
   195→		}
   196→		if json.Unmarshal(output2.Stdout, &blockResponse) == nil && blockResponse.Decision == "block" {
   197→			t.Errorf("Second prompt should not be blocked after warning was shown, got: %s", output2.Stdout)
   198→		}
   199→	}
   200→
   201→	// Warning flag should remain set (for tracking)
   202→	stateB, _ := env.GetSessionState(sessionB.ID)
   203→	if stateB == nil {
   204→		t.Fatal("Session B state should exist")
   205→	}
   206→	if !stateB.ConcurrentWarningShown {
   207→		t.Error("ConcurrentWarningShown should remain true after second prompt")
   208→	}
   209→
   210→	t.Log("Second prompt correctly processed (both sessions capture checkpoints)")
   211→}
