    92→	if err != nil {
    93→		return err
    94→	}
    95→
    96→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    97→	newRef := plumbing.NewHashReference(refName, newCommitHash)
    98→	if err := s.repo.Storer.SetReference(newRef); err != nil {
    99→		return fmt.Errorf("failed to set branch reference: %w", err)
   100→	}
   101→
   102→	return nil
   103→}
