   168→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
   169→func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   170→	checkpoint := taskCheckpointData{
   171→		SessionID:      opts.SessionID,
   172→		ToolUseID:      opts.ToolUseID,
   173→		CheckpointUUID: opts.CheckpointUUID,
   174→		AgentID:        opts.AgentID,
   175→	}
   176→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   177→	if err != nil {
   178→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
   179→	}
   180→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
   181→	if err != nil {
   182→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
   183→	}
   184→
   185→	checkpointFile := taskPath + "checkpoint.json"
   186→	entries[checkpointFile] = object.TreeEntry{
   187→		Name: checkpointFile,
   188→		Mode: filemode.Regular,
   189→		Hash: blobHash,
   190→	}
   191→
   192→	// Write subagent transcript if available
   193→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
   194→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
   195→		if readErr == nil {
   196→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
