   407→// readSummaryFromBlob reads CheckpointSummary from a blob hash.
   408→func (s *GitStore) readSummaryFromBlob(hash plumbing.Hash) (*CheckpointSummary, error) {
   409→	return readJSONFromBlob[CheckpointSummary](s.repo, hash)
   410→}
