   436→// writeTranscript writes the transcript file from in-memory content or file path.
   437→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   438→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   439→	transcript := opts.Transcript
   440→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   441→		var readErr error
   442→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   443→		if readErr != nil {
   444→			// Non-fatal: transcript may not exist yet
   445→			transcript = nil
   446→		}
   447→	}
   448→	if len(transcript) == 0 {
   449→		return nil
   450→	}
   451→
   452→	// Chunk the transcript if it's too large
   453→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   454→	if err != nil {
   455→		return fmt.Errorf("failed to chunk transcript: %w", err)
   456→	}
   457→
   458→	// Write chunk files
   459→	for i, chunk := range chunks {
   460→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   461→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   462→		if err != nil {
   463→			return err
   464→		}
   465→		entries[chunkPath] = object.TreeEntry{
   466→			Name: chunkPath,
   467→			Mode: filemode.Regular,
   468→			Hash: blobHash,
   469→		}
   470→	}
   471→
   472→	// Content hash for deduplication (hash of full transcript)
   473→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   474→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   475→	if err != nil {
   476→		return err
   477→	}
   478→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   479→		Name: basePath + paths.ContentHashFileName,
   480→		Mode: filemode.Regular,
   481→		Hash: hashBlob,
   482→	}
   483→	return nil
   484→}
   485→
   486→// mergeFilesTouched combines two file lists, removing duplicates.
   487→func mergeFilesTouched(existing, additional []string) []string {
   488→	seen := make(map[string]bool)
   489→	var result []string
   490→
   491→	for _, f := range existing {
   492→		if !seen[f] {
   493→			seen[f] = true
   494→			result = append(result, f)
   495→		}
   496→	}
   497→	for _, f := range additional {
   498→		if !seen[f] {
   499→			seen[f] = true
   500→			result = append(result, f)
   501→		}
   502→	}
   503→
   504→	sort.Strings(result)
   505→	return result
   506→}
