   513→// archiveExistingSession moves existing session files to a numbered subfolder.
   514→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   515→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   516→	// Determine archive folder number
   517→	sessionCount := existingMetadata.SessionCount
   518→	if sessionCount == 0 {
   519→		sessionCount = 1 // backwards compat
   520→	}
   521→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   522→
   523→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   524→	filesToArchive := []string{
   525→		paths.MetadataFileName,
   526→		paths.TranscriptFileName,
   527→		paths.PromptFileName,
   528→		paths.ContextFileName,
   529→		paths.ContentHashFileName,
   530→	}
   531→
   532→	// Also include transcript chunk files (full.jsonl.001, full.jsonl.002, etc.)
   533→	chunkPrefix := basePath + paths.TranscriptFileName + "."
   534→	for srcPath := range entries {
   535→		if strings.HasPrefix(srcPath, chunkPrefix) {
   536→			chunkSuffix := strings.TrimPrefix(srcPath, basePath+paths.TranscriptFileName)
   537→			if idx := agent.ParseChunkIndex(paths.TranscriptFileName+chunkSuffix, paths.TranscriptFileName); idx > 0 {
   538→				filesToArchive = append(filesToArchive, paths.TranscriptFileName+chunkSuffix)
   539→			}
   540→		}
   541→	}
   542→
   543→	// Move each file to archive folder
   544→	for _, filename := range filesToArchive {
   545→		srcPath := basePath + filename
   546→		if entry, exists := entries[srcPath]; exists {
   547→			// Add to archive location
   548→			dstPath := archivePath + filename
   549→			entries[dstPath] = object.TreeEntry{
   550→				Name: dstPath,
   551→				Mode: entry.Mode,
   552→				Hash: entry.Hash,
   553→			}
   554→			// Remove from original location (will be overwritten by new session)
   555→			delete(entries, srcPath)
   556→		}
   557→	}
   558→}
   559→
   560→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   561→// Returns sessions ordered by folder index (oldest first).
   562→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int, agentType agent.AgentType) []ArchivedSession {
   563→	var archived []ArchivedSession
   564→
   565→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   566→	// The most recent session is at the root level (not archived).
   567→	// Session count N means there are N-1 archived sessions.
   568→	for i := 1; i < sessionCount; i++ {
   569→		folderName := strconv.Itoa(i)
   570→
   571→		// Try to get the archived session subtree
   572→		subTree, err := checkpointTree.Tree(folderName)
   573→		if err != nil {
   574→			continue // Folder doesn't exist, skip
   575→		}
   576→
   577→		session := ArchivedSession{
   578→			FolderIndex: i,
   579→		}
   580→
   581→		// Read metadata to get session ID
   582→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   583→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   584→				var metadata CommittedMetadata
   585→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   586→					session.SessionID = metadata.SessionID
   587→				}
   588→			}
   589→		}
   590→
   591→		// Read transcript (handles both chunked and non-chunked formats)
   592→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   593→			session.Transcript = transcript
   594→		}
   595→
   596→		// Read prompts
   597→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   598→			if content, contentErr := file.Contents(); contentErr == nil {
   599→				session.Prompts = content
   600→			}
   601→		}
   602→
   603→		// Only add if we got a transcript
   604→		if len(session.Transcript) > 0 {
   605→			archived = append(archived, session)
   606→		}
   607→	}
   608→
   609→	return archived
   610→}
   611→
   612→// buildCommitMessage constructs the commit message with proper trailers.
   613→// The commit subject is always "Checkpoint: <id>" for consistency.
   614→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   615→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   616→	var commitMsg strings.Builder
   617→
   618→	// Subject line is always the checkpoint ID for consistent formatting
   619→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   620→
   621→	// Include custom description in body if provided (e.g., task checkpoint details)
   622→	if opts.CommitSubject != "" {
   623→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   624→	}
   625→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   626→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   627→	if opts.Agent != "" {
   628→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   629→	}
   630→	if opts.EphemeralBranch != "" {
   631→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   632→	}
   633→	if taskMetadataPath != "" {
   634→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   635→	}
   636→
   637→	return commitMsg.String()
   638→}
