   811→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   812→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   813→//
   814→
   815→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   816→	_ = ctx // Reserved for future use
   817→
   818→	tree, err := s.getSessionsBranchTree()
   819→	if err != nil {
   820→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   821→	}
   822→
   823→	var checkpoints []CommittedInfo
   824→
   825→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   826→	for _, bucketEntry := range tree.Entries {
   827→		if bucketEntry.Mode != filemode.Dir {
   828→			continue
   829→		}
   830→		// Bucket should be 2 hex chars
   831→		if len(bucketEntry.Name) != 2 {
   832→			continue
   833→		}
   834→
   835→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   836→		if treeErr != nil {
   837→			continue
   838→		}
   839→
   840→		// Each entry in the bucket is the remaining part of the checkpoint ID
   841→		for _, checkpointEntry := range bucketTree.Entries {
   842→			if checkpointEntry.Mode != filemode.Dir {
   843→				continue
   844→			}
   845→
   846→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   847→			if cpTreeErr != nil {
   848→				continue
   849→			}
   850→
   851→			// Reconstruct checkpoint ID: <bucket><remaining>
   852→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   853→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   854→			if cpIDErr != nil {
   855→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   856→				continue
   857→			}
   858→
   859→			info := CommittedInfo{
   860→				CheckpointID: checkpointID,
   861→			}
   862→
   863→			// Get details from root metadata file (CheckpointSummary format)
   864→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   865→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   866→					var summary CheckpointSummary
   867→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
   868→						info.CheckpointsCount = summary.CheckpointsCount
   869→						info.FilesTouched = summary.FilesTouched
   870→						info.SessionCount = len(summary.Sessions)
   871→
   872→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
   873→						if len(summary.Sessions) > 0 {
   874→							latestIndex := len(summary.Sessions)
   875→							latestDir := strconv.Itoa(latestIndex)
   876→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   877→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
   878→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
   879→										var sessionMetadata CommittedMetadata
   880→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   881→											info.Agent = sessionMetadata.Agent
   882→											info.SessionID = sessionMetadata.SessionID
   883→											info.CreatedAt = sessionMetadata.CreatedAt
   884→										}
   885→									}
   886→								}
   887→							}
   888→						}
   889→					}
   890→				}
   891→			}
   892→
   893→			checkpoints = append(checkpoints, info)
   894→		}
   895→	}
   896→
   897→	// Sort by time (most recent first)
   898→	sort.Slice(checkpoints, func(i, j int) bool {
   899→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   900→	})
   901→
   902→	return checkpoints, nil
   903→}
