   952→// UpdateSummary updates the summary field in the latest session's metadata.
   953→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   954→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   955→	_ = ctx // Reserved for future use
   956→
   957→	// Ensure sessions branch exists
   958→	if err := s.ensureSessionsBranch(); err != nil {
   959→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
   960→	}
   961→
   962→	// Get current branch tip and flatten tree
   963→	ref, entries, err := s.getSessionsBranchEntries()
   964→	if err != nil {
   965→		return err
   966→	}
   967→
   968→	// Read root CheckpointSummary to find the latest session
   969→	basePath := checkpointID.Path() + "/"
   970→	rootMetadataPath := basePath + paths.MetadataFileName
   971→	entry, exists := entries[rootMetadataPath]
   972→	if !exists {
   973→		return ErrCheckpointNotFound
   974→	}
   975→
   976→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
   977→	if err != nil {
   978→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
   979→	}
   980→
   981→	// Find the latest session's metadata path (1-based indexing)
   982→	latestIndex := len(checkpointSummary.Sessions)
   983→	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
   984→	sessionEntry, exists := entries[sessionMetadataPath]
   985→	if !exists {
   986→		return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
   987→	}
   988→
   989→	// Read and update session metadata
   990→	existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
   991→	if err != nil {
   992→		return fmt.Errorf("failed to read session metadata: %w", err)
   993→	}
   994→
   995→	// Update the summary
   996→	existingMetadata.Summary = summary
   997→
   998→	// Write updated session metadata
   999→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
  1000→	if err != nil {
  1001→		return fmt.Errorf("failed to marshal metadata: %w", err)
  1002→	}
  1003→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
  1004→	if err != nil {
  1005→		return fmt.Errorf("failed to create metadata blob: %w", err)
  1006→	}
  1007→	entries[sessionMetadataPath] = object.TreeEntry{
  1008→		Name: sessionMetadataPath,
  1009→		Mode: filemode.Regular,
  1010→		Hash: metadataHash,
  1011→	}
  1012→
  1013→	// Build and commit
  1014→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
  1015→	if err != nil {
  1016→		return err
  1017→	}
  1018→
  1019→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
  1020→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
  1021→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
  1022→	if err != nil {
  1023→		return err
  1024→	}
  1025→
  1026→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1027→	newRef := plumbing.NewHashReference(refName, newCommitHash)
  1028→	if err := s.repo.Storer.SetReference(newRef); err != nil {
  1029→		return fmt.Errorf("failed to set branch reference: %w", err)
  1030→	}
  1031→
  1032→	return nil
  1033→}
