  1035→// ensureSessionsBranch ensures the entire/sessions branch exists.
  1036→func (s *GitStore) ensureSessionsBranch() error {
  1037→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1038→	_, err := s.repo.Reference(refName, true)
  1039→	if err == nil {
  1040→		return nil // Branch exists
  1041→	}
  1042→
  1043→	// Create orphan branch with empty tree
  1044→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
  1045→	if err != nil {
  1046→		return err
  1047→	}
  1048→
  1049→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
  1050→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
  1051→	if err != nil {
  1052→		return err
  1053→	}
  1054→
  1055→	newRef := plumbing.NewHashReference(refName, commitHash)
  1056→	if err := s.repo.Storer.SetReference(newRef); err != nil {
  1057→		return fmt.Errorf("failed to set branch reference: %w", err)
  1058→	}
  1059→	return nil
  1060→}
