  1083→// CreateBlobFromContent creates a blob object from in-memory content.
  1084→// Exported for use by strategy package (session_test.go)
  1085→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1086→	obj := repo.Storer.NewEncodedObject()
  1087→	obj.SetType(plumbing.BlobObject)
  1088→	obj.SetSize(int64(len(content)))
  1089→
  1090→	writer, err := obj.Writer()
  1091→	if err != nil {
  1092→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1093→	}
  1094→
  1095→	_, err = writer.Write(content)
  1096→	if err != nil {
  1097→		_ = writer.Close()
  1098→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1099→	}
  1100→	if err := writer.Close(); err != nil {
  1101→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1102→	}
  1103→
  1104→	hash, err := repo.Storer.SetEncodedObject(obj)
  1105→	if err != nil {
  1106→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1107→	}
  1108→	return hash, nil
  1109→}
