  1111→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1112→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1113→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1114→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1115→		if err != nil {
  1116→			return err
  1117→		}
  1118→		if info.IsDir() {
  1119→			return nil
  1120→		}
  1121→
  1122→		// Skip symlinks to prevent reading files outside the metadata directory.
  1123→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1124→		// then be captured in the checkpoint and stored in git history.
  1125→		if info.Mode()&os.ModeSymlink != 0 {
  1126→			return nil
  1127→		}
  1128→
  1129→		// Get relative path within metadata dir
  1130→		relPath, err := filepath.Rel(metadataDir, path)
  1131→		if err != nil {
  1132→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1133→		}
  1134→
  1135→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1136→		if strings.HasPrefix(relPath, "..") {
  1137→			return fmt.Errorf("path traversal detected: %s", relPath)
  1138→		}
  1139→
  1140→		// Create blob from file
  1141→		blobHash, mode, err := createBlobFromFile(s.repo, path)
  1142→		if err != nil {
  1143→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1144→		}
  1145→
  1146→		// Store at checkpoint path
  1147→		fullPath := basePath + relPath
  1148→		entries[fullPath] = object.TreeEntry{
  1149→			Name: fullPath,
  1150→			Mode: mode,
  1151→			Hash: blobHash,
  1152→		}
  1153→
  1154→		return nil
  1155→	})
  1156→	if err != nil {
  1157→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1158→	}
  1159→	return nil
  1160→}
