  1162→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1163→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1164→	// Get repository config (includes local settings)
  1165→	cfg, err := repo.Config()
  1166→	if err == nil {
  1167→		name = cfg.User.Name
  1168→		email = cfg.User.Email
  1169→	}
  1170→
  1171→	// Provide sensible defaults if git user is not configured
  1172→	if name == "" {
  1173→		name = "Unknown"
  1174→	}
  1175→	if email == "" {
  1176→		email = "unknown@local"
  1177→	}
  1178→
  1179→	return name, email
  1180→}
