  1182→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1183→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1184→// The agentType is used for reassembling chunks in the correct format.
  1185→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1186→	// Collect all transcript-related files
  1187→	var chunkFiles []string
  1188→	var hasBaseFile bool
  1189→
  1190→	for _, entry := range tree.Entries {
  1191→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1192→			hasBaseFile = true
  1193→		}
  1194→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1195→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1196→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1197→			if idx > 0 {
  1198→				chunkFiles = append(chunkFiles, entry.Name)
  1199→			}
  1200→		}
  1201→	}
  1202→
  1203→	// If we have chunk files, read and reassemble them
  1204→	if len(chunkFiles) > 0 {
  1205→		// Sort chunk files by index
  1206→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1207→
  1208→		// Check if base file should be included as chunk 0.
  1209→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1210→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1211→		if hasBaseFile {
  1212→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1213→		}
  1214→
  1215→		var chunks [][]byte
  1216→		for _, chunkFile := range chunkFiles {
  1217→			file, err := tree.File(chunkFile)
  1218→			if err != nil {
  1219→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1220→					slog.String("chunk_file", chunkFile),
  1221→					slog.String("error", err.Error()),
  1222→				)
  1223→				continue
  1224→			}
  1225→			content, err := file.Contents()
  1226→			if err != nil {
  1227→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1228→					slog.String("chunk_file", chunkFile),
  1229→					slog.String("error", err.Error()),
  1230→				)
  1231→				continue
  1232→			}
  1233→			chunks = append(chunks, []byte(content))
  1234→		}
  1235→
  1236→		if len(chunks) > 0 {
  1237→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1238→			if err != nil {
  1239→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1240→			}
  1241→			return result, nil
  1242→		}
  1243→	}
  1244→
  1245→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1246→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1247→		if content, err := file.Contents(); err == nil {
  1248→			return []byte(content), nil
  1249→		}
  1250→	}
  1251→
  1252→	// Try legacy filename
  1253→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1254→		if content, err := file.Contents(); err == nil {
  1255→			return []byte(content), nil
  1256→		}
  1257→	}
  1258→
  1259→	return nil, nil
  1260→}
